DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.rpc_create_notificacao_operacional(uuid,text,text,text,text,text,uuid,text)'::regprocedure) INTO d; d:=replace(d,$old$_link !~ '^/[A-Za-z0-9_\-./?=&%#]{0,500}$'$old$,$new$(length(_link)>501 OR _link !~ '^/[A-Za-z0-9_\-./?=&%#]*$' OR _link LIKE '//%' OR _link LIKE '%..%')$new$); IF d LIKE '%{0,500}%' THEN RAISE EXCEPTION 'BASELINE_MISMATCH'; END IF; EXECUTE d; END $$;